module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    input  e,
    output [24:0] out
);

    // The specification asks for all 25 pairwise comparisons of 5 bits.
    // The comparison is "1 if the two bits are equal".
    // This is equivalent to the XNOR operation: ~(x ^ y).

    // The example provided:
    // out[24] = ~a ^ a  (which is a XNOR a)
    // out[23] = ~a ^ b  (which is a XNOR b)
    // ...
    // out[0]  = ~e ^ e  (which is e XNOR e)

    // Mapping the 5 inputs to an array for easier indexing
    wire [4:0] inputs = {a, b, c, d, e};

    // We need to generate 25 combinations.
    // The pattern follows a nested loop structure:
    // For i from 0 to 4:
    //   For j from 0 to 4:
    //     out[24 - (i*5 + j)] = ~(inputs[i] ^ inputs[j])

    genvar i, j;
    generate
        for (i = 0; i < 5; i = i + 1) begin : row
            for (j = 0; j < 5; j = j + 1) begin : col
                assign out[24 - (i*5 + j)] = ~(inputs[i] ^ inputs[j]);
            end
        end
    endgenerate

endmodule

