module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    // Register to store the state of the input from the previous clock cycle
    logic [31:0] in_prev;

    always_ff @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: clear the history and the output capture register
            in_prev <= 32'b0;
            out     <= 32'b0;
        end else begin
            // Update the history register for the next cycle
            in_prev <= in;

            // Capture logic:
            // A bit is set to 1 if it was 1 in the previous cycle and is 0 in the current cycle.
            // Once a bit in 'out' becomes 1, it stays 1 until reset.
            // The expression (in_prev & ~in) detects the 1 -> 0 transition.
            out <= out | (in_prev & ~in);
        end
    end

endmodule

