    // Galois LFSR Logic
    // Specification: 5-bit maximal-length Galois LFSR
    // Taps at bit positions 5 and 3.
    // In a Galois LFSR shifting right:
    // The LSB (q[0]) is XORed with the bits at the tap positions.
    // For a 5-bit register (indices 4 down to 0):
    // Bit 5 (the input to the MSB) is XORed with q[0].
    // Bit 3 (the input to index 2) is XORed with q[0].

    // Mapping "Bit positions 5 and 3" to 0-indexed 5-bit register:
    // Position 5 -> index 4 (MSB)
    // Position 3 -> index 2

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset to 1 (00001)
            lfsr_reg <= 5'b00001;
        end else begin
            // Galois shift right logic:
            // next_q[4] = q[0] (Tap at 5)
            // next_q[3] = q[4]
            // next_q[2] = q[3] ^ q[0] (Tap at 3)
            // next_q[1] = q[2]
            // next_q[0] = q[1]
            lfsr_reg <= {lfsr_reg[0], 
                        lfsr_reg[4], 
                        lfsr_reg[3] ^ lfsr_reg[0], 
                        lfsr_reg[2], 
                        lfsr_reg[1]};
        end
    end

endmodule

