);

    // State definitions
    typedef enum logic {
        STATE_WALK_LEFT  = 1'b0,
        STATE_WALK_RIGHT = 1'b1
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            STATE_WALK_LEFT: begin
