        SEARCH = 2'b00, // Searching for the first byte (in[3] == 1)
        BYTE2  = 2'b01, // Received byte 1, waiting for byte 2
        BYTE3  = 2'b10  // Received byte 2, waiting for byte 3
    } state_t;

