module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // State definitions
    typedef enum logic [2:0] {
        IDLE      = 3'd0,
        START_BIT = 3'd1,
        DATA_BITS = 3'd2,
        STOP_BIT  = 3'd3,
        WAIT_STOP = 3'd4
    } state_t;

    state_t state;
    logic [3:0] bit_count;

    // Output logic
    assign done = (state == STOP_BIT) && (in == 1'b1);

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    // Look for start bit (0)
                    if (in == 1'b0) begin
                        state <= START_BIT;
                        bit_count <= 4'd0;
                    end else begin
                        state <= IDLE;
                    end
                end

                START_BIT: begin
                    // After start bit, move to receive 8 data bits
                    state <= DATA_BITS;
                    bit_count <= 4'd0;
                end

                DATA_BITS: begin
                    // Count 8 data bits
                    if (bit_count == 4'd7) begin
                        state <= STOP_BIT;
                    end else begin
                        bit_count <= bit_count + 4'd1;
                        state <= DATA_BITS;
                    end
                end

                STOP_BIT: begin
                    // Verify stop bit (1)
                    if (in == 1'b1) begin
                        state <= IDLE;
                    end else begin
                        // Framing error: stop bit missing
                        state <= WAIT_STOP;
                    end
                end

                WAIT_STOP: begin
                    // Wait until line returns to 1 before looking for next start bit
                    if (in == 1'b1) begin
                        state <= IDLE;
                    end else begin
                        state <= WAIT_STOP;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

