module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output reg z
);

    // State definitions
    // State A: Waiting for s=1 to start the sequence
    // State B: 1st cycle of w check
    // State C: 2nd cycle of w check
    // State D: 3rd cycle of w check
    typedef enum logic [2:0] {
        A = 3'b000,
        B = 3'b001,
        C = 3'b010,
        D = 3'b011
    } state_t;

    state_t state, next_state;

    // Counters to track how many times w=1 occurred in the 3-cycle window
    reg [1:0] w_count;

    // State Transition Logic
    always @(posedge clk) begin
        if (reset) begin
            state <= A;
            w_count <= 2'b00;
        end else begin
            state <= next_state;

            // Update w_count based on current state and input w
            if (state == A) begin
                w_count <= 2'b00;
            end else if (state == B || state == C || state == D) begin
                if (state == D) begin
                    // Reset count for the next window after the 3rd cycle
                    w_count <= (w) ? 2'b01 : 2'b00;
                end else begin
                    // Increment count if w is high
                    if (w) w_count <= w_count + 1'b1;
                end
            end
        end
    end

    // Next State Logic
    always @(*) begin
        next_state = state;
        case (state)
            A: begin
                if (s) next_state = B;
                else    next_state = A;
            end
            B: next_state = C;
            C: next_state = D;
            D: next_state = B;
            default: next_state = A;
        endcase
    end

    // Output Logic
    // z is 1 in the clock cycle following the 3rd cycle (state D) 
    // if exactly two w's were 1 in the window.
    // The window consists of w at state B, w at state C, and w at state D.
    always @(posedge clk) begin
        if (reset) begin
            z <= 1'b0;
        end else begin
            if (state == D) begin
                // Calculate total w's in the window: 
                // w_count (from B and C) + current w (at D)
                if ((w_count + w) == 2'd2) begin
                    z <= 1'b1;
                end else begin
                    z <= 1'b0;
                end
            end else begin
                z <= 1'b0;
            end
        end
    end

endmodule

