    // We need to track the walking direction even while falling.
    // States: 
    // 0: Walking Left
    // 1: Walking Right
    // 2: Falling (was walking left)
    // 3: Falling (was walking right)
    typedef enum logic [1:0] {
        WALK_L = 2'b00,
        WALK_R = 2'b01,
        FALL_L = 2'b10,
        FALL_R = 2'b11
