    always_comb begin
        next_state = current_state;
        case (current_state)
            WALK_L: begin
                if (!ground) begin
                    next_state = FALL_L;
                end else if (bump_left) begin
                    // Bumped on left -> walk right
                    // If bumped on both, specification says "still switch directions"
                    // Since we are walking left, switching means walking right.
                    next_state = WALK_R;
                end else if (bump_right) begin
                    // Bumped on right -> walk left (already walking left)
                    next_state = WALK_L;
                end
