            FALL_L: begin
                if (ground) begin
                    next_state = WALK_L;
                end
                // Bumps while falling are ignored
            end
            FALL_R: begin
                if (ground) begin
                    next_state = WALK_R;
                end
                // Bumps while falling are ignored
            end
            default: next_state = WALK_L;
        endcase
    end

    // Sequential logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_L;
        end else begin
            current_state <= next_state;
        end
    end

    // Moore output logic
    assign walk_left  = (current_state == WALK_L);
    assign walk_right = (current_state == WALK_R);
    assign aaah       = (current_state == FALL_L || current_state == FALL_R);

