// TopModule implements the combinational logic for a Moore state machine
// based on the provided state transition table and state encoding.
// State Encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11.

module TopModule (
    input  in,
    input  [1:0] state,
    output reg [1:0] next_state,
    output reg out
);

    // State encoding constants
    localparam A = 2'b00;
    localparam B = 2'b01;
    localparam C = 2'b10;
    localparam D = 2'b11;

    // Combinational logic for next_state
    always @(*) begin
        case (state)
            A: next_state = (in == 1'b0) ? A : B;
            B: next_state = (in == 1'b0) ? C : B;
            C: next_state = (in == 1'b0) ? A : D;
            D: next_state = (in == 1'b0) ? C : B;
            default: next_state = A;
        endcase
    end

    // Combinational logic for output (Moore machine: output depends only on state)
    always @(*) begin
        case (state)
            A: out = 1'b0;
            B: out = 1'b0;
            C: out = 1'b0;
            D: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

endmodule

