module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // State encoding for strict Moore Machine
    typedef enum logic [1:0] {
        S_ZERO  = 2'b00, // Initial state: output 0, waiting for first 1
        S_ONE   = 2'b01, // First 1 encountered: output 1
        S_INV0  = 2'b10, // Inverting: input was 0, output 1
        S_INV1  = 2'b11  // Inverting: input was 1, output 0
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always_comb begin
        case (current_state)
            S_ZERO: begin
                if (x == 1'b1) next_state = S_ONE;
                else           next_state = S_ZERO;
            end
            S_ONE: begin
                if (x == 1'b0) next_state = S_INV0;
                else           next_state = S_INV1;
            end
            S_INV0: begin
                if (x == 1'b0) next_state = S_INV0;
                else           next_state = S_INV1;
            end
            S_INV1: begin
                if (x == 1'b0) next_state = S_INV0;
                else           next_state = S_INV1;
            end
            default: next_state = S_ZERO;
        endcase
    end

    // Sequential logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S_ZERO;
        end else begin
            current_state <= next_state;
        end
    end

    // Moore output logic: z depends only on current_state
    assign z = (current_state == S_ONE || current_state == S_INV0);

endmodule

