module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot state encoding
    // State A: 2'b01
    // State B: 2'b10
    typedef enum logic [1:0] {
        STATE_A = 2'b01,
        STATE_B = 2'b10
    } state_t;

    state_t current_state, next_state;
    logic z_comb;

    // State transition logic (Sequential)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= STATE_A;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic (Combinational)
    always_comb begin
        case (current_state)
            STATE_A: begin
                if (x == 1'b0)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end
            STATE_B: begin
                // Both x=0 and x=1 transition back to B
                next_state = STATE_B;
            end
            default: begin
                next_state = STATE_A;
            end
        endcase
    end

    // Output logic (Mealy: depends on current state and input x)
    always_comb begin
        case (current_state)
            STATE_A: begin
                if (x == 1'b0)
                    z_comb = 1'b0;
                else
                    z_comb = 1'b1;
            end
            STATE_B: begin
                if (x == 1'b0)
                    z_comb = 1'b1;
                else
                    z_comb = 1'b0;
            end
            default: begin
                z_comb = 1'b0;
            end
        endcase
    end

    // Assign combinational output to port
    assign z = z_comb;

endmodule

Prob146_fsm_serialdata.code:
module TopModule (
    input  clk,
    input  in,
    input  reset,
    output logic [7:0] out_byte,
    output logic done
);

    // State definitions
    typedef enum logic [2:0] {
        IDLE    = 3'b000,
        START   = 3'b001,
        DATA    = 3'b010,
        STOP    = 3'b011,
        WAIT_1  = 3'b100
    } state_t;

    state_t state;
    logic [2:0] bit_cnt;
    logic [7:0] shift_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            bit_cnt   <= 3'b000;
            shift_reg <= 8'b0;
            out_byte  <= 8'b0;
            done      <= 1'b0;
        end else begin
            done <= 1'b0; // Default value

            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START;
                    end
                end

                START: begin
                    // We have detected the start bit (0). 
                    // Now we move to collect 8 data bits.
                    state   <= DATA;
                    bit_cnt <= 3'b000;
                end

                DATA: begin
                    // LSB first: shift in from the right
                    shift_reg <= {in, shift_reg[7:1]};
                    if (bit_cnt == 3'd7) begin
                        state   <= STOP;
                        bit_cnt <= 3'b000;
                    end else begin
                        bit_cnt <= bit_cnt + 1'b1;
                    end
                end

                STOP: begin
                    if (in == 1'b1) begin
                        // Correct stop bit received
                        out_byte <= shift_reg;
                        done     <= 1'b1;
                        state    <= IDLE;
                    end else begin
                        // Stop bit missing: wait until line is 1
                        state    <= WAIT_1;
                    end
                end

                WAIT_1: begin
                    if (in == 1'b1) begin
                        // Found a stop bit (or idle line), now we can look for next start bit
                        done  <= 1'b1; // Specification: "assert done each time it finds a stop bit"
                        state <= IDLE;
                    end
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

