module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal state to hold the grid
    logic [255:0] current_grid;
    logic [255:0] next_grid;

    // Helper function to get cell state with toroidal wrapping
    function logic get_cell(logic [255:0] grid, int row, int col);
        // Wrap row and col to [0, 15]
        int r = (row + 16) % 16;
        int c = (col + 16) % 16;
        get_cell = grid[r * 16 + c];
    endfunction

    // Combinational logic to calculate the next state of the grid
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                // Count 8 neighbors
                logic [3:0] neighbors;
                neighbors = 0;
                neighbors += get_cell(current_grid, r-1, c-1);
                neighbors += get_cell(current_grid, r-1, c);
                neighbors += get_cell(current_grid, r-1, c+1);
                neighbors += get_cell(current_grid, r,   c-1);
                neighbors += get_cell(current_grid, r,   c+1);
                neighbors += get_cell(current_grid, r+1, c-1);
                neighbors += get_cell(current_grid, r+1, c);
                neighbors += get_cell(current_grid, r+1, c+1);

                // Apply Game of Life rules:
                // (1) 0-1 neighbour: Cell becomes 0.
                // (2) 2 neighbours: Cell state does not change.
                // (3) 3 neighbours: Cell becomes 1.
                // (4) 4+ neighbours: Cell becomes 0.
                if (neighbors == 3) begin
                    next_grid[r * 16 + c] = 1'b1;
                end else if (neighbors == 2) begin
                    next_grid[r * 16 + c] = current_grid[r * 16 + c];
                end else begin
                    next_grid[r * 16 + c] = 1'b0;
                end
            end
        end
    end

    // Sequential logic for state updates
    always_ff @(posedge clk) begin
        if (load) begin
            current_grid <= data;
        end else begin
            current_grid <= next_grid;
        end
    end

    // Output assignment
    assign q = current_grid;

endmodule

