`timescale 1ns/1ps

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State definitions
    // We need to track the walking direction even when falling or digging.
    // States: 
    // 0: Walking Left
    // 1: Walking Right
    // 2: Falling (was walking left)
    // 3: Falling (was walking right)
    // 4: Digging (was walking left)
    // 5: Digging (was walking right)

    typedef enum logic [2:0] {
        WALK_L = 3'd0,
        WALK_R = 3'd1,
        FALL_L = 3'd2,
        FALL_R = 3'd3,
        DIG_L  = 3'd4,
        DIG_R  = 3'd5
    } state_t;

    state_t state, next_state;

    // State Transition Logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_L;
        end else begin
            state <= next_state;
        end
    end

    // Next State Combinational Logic
    always_comb begin
        next_state = state;

        case (state)
            WALK_L: begin
                if (!ground) 
                    next_state = FALL_L;
                else if (dig) 
                    next_state = DIG_L;
                else if (bump_left) 
                    next_state = WALK_R;
                else 
                    next_state = WALK_L;
            end

            WALK_R: begin
                if (!ground) 
                    next_state = FALL_R;
                else if (dig) 
                    next_state = DIG_R;
                else if (bump_right) 
                    next_state = WALK_L;
                else 
                    next_state = WALK_R;
            end

            FALL_L: begin
                if (ground) 
                    next_state = WALK_L;
                else 
                    next_state = FALL_L;
            end

            FALL_R: begin
                if (ground) 
                    next_state = WALK_R;
                else 
                    next_state = FALL_R;
            end

            DIG_L: begin
                if (!ground) 
                    next_state = FALL_L;
                else 
                    next_state = DIG_L;
            end

            DIG_R: begin
                if (!ground) 
                    next_state = FALL_R;
                else 
                    next_state = DIG_R;
            end

            default: next_state = WALK_L;
        endcase
    end

    // Output Logic (Moore Machine)
    assign walk_left  = (state == WALK_L);
    assign walk_right = (state == WALK_R);
    assign aaah       = (state == FALL_L || state == FALL_R);
    assign digging    = (state == DIG_L  || state == DIG_R);

endmodule

