module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // Gshare parameters: 7-bit PC, 7-bit History -> 7-bit Index (128 entries)
    // PHT: 128 entries of 2-bit saturating counters
    logic [1:0] pht [0:127];
    logic [6:0] ghr;

    // Index calculation: PC XOR History
    wire [6:0] predict_idx = predict_pc ^ ghr;
    wire [6:0] train_idx   = train_pc ^ train_history;

    // Prediction Logic
    // Predict taken if the counter is 2 or 3 (strong/weak taken)
    assign predict_taken = (predict_valid) ? (pht[predict_idx][1]) : 1'b0;
    assign predict_history = ghr;

    // Sequential Logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // Initialize PHT to 0 (Strongly Not Taken) or 1 (Weakly Not Taken)
            // Standard gshare usually starts at 1 or 0.
            for (int i = 0; i < 128; i++) begin
                pht[i] <= 2'b00;
            end
        end else begin
            // PHT Update (Training)
            if (train_valid) begin
                if (train_taken) begin
                    // Increment saturating counter
                    if (pht[train_idx] < 2'b11)
                        pht[train_idx] <= pht[train_idx] + 1'b1;
                end else begin
                    // Decrement saturating counter
                    if (pht[train_idx] > 2'b00)
                        pht[train_idx] <= pht[train_idx] - 1'b1;
                end
            end

            // GHR Update
            // Priority: 1. Training Misprediction Recovery, 2. Prediction Update
            if (train_valid && train_mispredicted) begin
                // Recover GHR to state immediately after the mispredicting branch
                // New GHR = (Old GHR << 1) | actual_outcome
                ghr <= {train_history[5:0], train_taken};
            end else if (predict_valid) begin
                // Speculatively update GHR based on prediction
                ghr <= {ghr[5:0], predict_taken};
            end
        end
    end

endmodule

