    input  logic        load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state of the cellular automaton
    logic [511:0] state_reg;

    // Temporary variables for the loop to avoid "automatic" keyword issues
    // and to ensure we use the current state for all calculations before updating.
    logic [511:0] next_state;

    always_comb begin
        for (int i = 0; i < 512; i++) begin
            logic left, center, right;

            // Boundary conditions: q[-1] and q[512] are 0
            left   = (i == 511) ? 1'b0 : state_reg[i+1];
            center = state_reg[i];
            right  = (i == 0)    ? 1'b0 : state_reg[i-1];

            case ({left, center, right})
                3'b111: next_state[i] = 1'b0;
                3'b110: next_state[i] = 1'b1;
                3'b101: next_state[i] = 1'b1;
                3'b100: next_state[i] = 1'b0;
                3'b011: next_state[i] = 1'b1;
                3'b010: next_state[i] = 1'b1;
                3'b001: next_state[i] = 1'b1;
                3'b000: next_state[i] = 1'b0;
                default: next_state[i] = 1'b0;
            endcase
        end
    end

    always_ff @(posedge clk) begin
        if (load) begin
            state_reg <= data;
        end else begin
            state_reg <= next_state;
        end
    end

    // Output assignment
    assign q = state_reg;

endmodule

