 * 
 * Specification:
 * p1y = (p1a AND p1b AND p1c) OR (p1d AND p1e AND p1f)
 * p2y = (p2a AND p2b) OR (p2c AND p2d)
 */

module TopModule (
    input  p1a,
    input  p1b,
    input  p1c,
    input  p1d,
    input  p1e,
    input  p1f,
    input  p2a,
    input  p2b,
    input  p2c,
    input  p2d,
    output p1y,
    output p2y
);

    // Intermediate wires for the four AND gates
    wire and1_out;
    wire and2_out;
    wire and3_out;
    wire and4_out;

    // First 3-input AND gate
    assign and1_out = p1a & p1b & p1c;
    // Second 3-input AND gate
    assign and2_out = p1d & p1e & p1f;
    // Third 2-input AND gate
    assign and3_out = p2a & p2b;
    // Fourth 2-input AND gate
    assign and4_out = p2c & p2d;

    // OR gates to drive the final outputs
    assign p1y = and1_out | and2_out;
    assign p2y = and3_out | and4_out;

endmodule

Prob109_fsm1.code:
module TopModule (
    input  clk,
    input  areset,
    input  in,
    output out
);

    // State encoding
    typedef enum logic {
        STATE_A = 1'b0,
        STATE_B = 1'b1
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always_comb begin
        case (current_state)
            STATE_A: begin
                if (in == 1'b0)
                    next_state = STATE_B;
                else
                    next_state = STATE_A;
            end
            STATE_B: begin
                if (in == 1'b0)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end
            default: next_state = STATE_B;
        endcase
    end

    // State register with asynchronous reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= STATE_B;
        end else begin
            current_state <= next_state;
        end
    end

    // Moore output logic
    // State A outputs 0, State B outputs 1
    assign out = (current_state == STATE_B);

endmodule

Prob108_rule90.code:
module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state of the cellular automaton
    logic [511:0] state_reg;

    // Temporary variables for the loop to avoid "automatic" keyword issues
    logic left;
    logic right;

    always_ff @(posedge clk) begin
        if (load) begin
            // Load the initial state from the data input
            state_reg <= data;
        end else begin
            // Rule 90: The next state of a cell is the XOR of its two neighbors.
            // Boundary conditions: q[-1] = 0 and q[512] = 0.
            for (int i = 0; i < 512; i++) begin
                left  = (i == 0)   ? 1'b0 : state_reg[i-1];
                right = (i == 511) ? 1'b0 : state_reg[i+1];
                state_reg[i] <= left ^ right;
            end
        end
    end

    // Assign the internal state to the output port
    assign q = state_reg;

endmodule

Prob115_shift18.code:
module TopModule (
    input  clk,
    input  load,
    input  ena,
    input  [1:0] amount,
    input  [63:0] data,
    output [63:0] q
);

    // Internal register to hold the shifter state
    reg [63:0] shift_reg;

    // Output assignment
    assign q = shift_reg;

    always @(posedge clk) begin
        if (load) begin
            // Synchronous load takes priority over shifting
            shift_reg <= data;
        end else if (ena) begin
            // Perform shift based on the amount input
            case (amount)
                2'b00: begin
                    // Shift left by 1 bit
                    shift_reg <= shift_reg << 1;
                end
                2'b01: begin
                    // Shift left by 8 bits
                    shift_reg <= shift_reg << 8;
                end
                2'b10: begin
                    // Arithmetic shift right by 1 bit
                    // Casting to signed ensures the >>> operator performs sign extension
                    shift_reg <= $signed(shift_reg) >>> 1;
                end
                2'b11: begin
                    // Arithmetic shift right by 8 bits
                    shift_reg <= $signed(shift_reg) >>> 8;
                end
                default: begin
                    shift_reg <= shift_reg;
                end
            endcase
        end
        // If neither load nor ena is active, shift_reg retains its value
    end

endmodule

