module TopModule (
    input  clk,
    input  enable,
    input  S,
    input  A,
    input  B,
    input  C,
    output Z
);

    // 8-bit shift register to store the memory
    // Q[0] is the first flip-flop (receives S), Q[7] is the last.
    reg [7:0] Q;

    always @(posedge clk) begin
        if (enable) begin
            // Shift register logic:
            // S feeds Q[0], Q[0] feeds Q[1], ..., Q[6] feeds Q[7]
            Q[0] <= S;
            Q[1] <= Q[0];
            Q[2] <= Q[1];
            Q[3] <= Q[2];
            Q[4] <= Q[3];
            Q[5] <= Q[4];
            Q[6] <= Q[5];
            Q[7] <= Q[6];
        end
    end

    // Multiplexer to implement random access reading based on ABC
    // ABC = 000 -> Z = Q[0]
    // ABC = 001 -> Z = Q[1]
    // ...
    // ABC = 111 -> Z = Q[7]
    assign Z = ( {A, B, C} == 3'b000 ) ? Q[0] :
               ( {A, B, C} == 3'b001 ) ? Q[1] :
               ( {A, B, C} == 3'b010 ) ? Q[2] :
               ( {A, B, C} == 3'b011 ) ? Q[3] :
               ( {A, B, C} == 3'b100 ) ? Q[4] :
               ( {A, B, C} == 3'b101 ) ? Q[5] :
               ( {A, B, C} == 3'b110 ) ? Q[6] :
               ( {A, B, C} == 3'b111 ) ? Q[7] : 1'b0;

endmodule

